//! (c) yFoil functionality: `yfoil plot foil | analysis | polar` end to end through the binary:
//! geometry, analysis and polar inputs, the ironlab figures they write (loaded back and checked
//! for their axes, artists, key, links, parameters and labels), and the input-dispatch errors.
//! Needs the `plotting` feature.
//!
//! Fixtures: none (every input is generated by the binary).
#![cfg(feature = "plotting")]

use std::path::{Path, PathBuf};
use std::process::Command;

use ironlab::ir::{Artist, Dimension, Line, Parameter};
use ironlab::Figure;
use yfoil::output::AnalysisOutput;

fn yfoil() -> Command {
    Command::new(env!("CARGO_BIN_EXE_yfoil"))
}

fn run_in(dir: Option<&Path>, args: &[&str]) -> (bool, String, String) {
    let mut cmd = yfoil();
    if let Some(dir) = dir {
        cmd.current_dir(dir);
    }
    let out = cmd.args(args).output().expect("run yfoil");
    (
        out.status.success(),
        String::from_utf8_lossy(&out.stdout).to_string(),
        String::from_utf8_lossy(&out.stderr).to_string(),
    )
}

fn ok_in(dir: Option<&Path>, args: &[&str]) -> String {
    let (success, stdout, stderr) = run_in(dir, args);
    assert!(success, "yfoil {:?} failed:\n{stdout}\n{stderr}", args);
    stdout
}

fn ok(args: &[&str]) -> String {
    ok_in(None, args)
}

fn fails(args: &[&str], needle: &str) {
    let (success, stdout, stderr) = run_in(None, args);
    assert!(!success, "yfoil {:?} unexpectedly succeeded:\n{stdout}", args);
    assert!(
        stderr.contains(needle),
        "yfoil {:?}: stderr lacks '{needle}':\n{stderr}",
        args
    );
}

struct Case {
    dir: tempfile::TempDir,
}

impl Case {
    fn new() -> Self {
        let dir = tempfile::tempdir().unwrap();
        let c = Self { dir };
        ok(&["geometry", "naca", "0012", "-n", "60", "-o", c.p("n0012.json")]);
        ok(&["geometry", "naca", "0012", "-n", "40", "-o", c.p("n0012_40.json")]);
        ok(&[
            "analyse",
            c.p("n0012.json"),
            "--alpha",
            "4",
            "-r",
            "1e6",
            "-o",
            c.p("a4.json"),
        ]);
        ok(&[
            "analyse",
            c.p("n0012.json"),
            "--alpha",
            "4",
            "-r",
            "1e6",
            "-m",
            "0.3",
            "-o",
            c.p("a4m3.json"),
        ]);
        c
    }

    fn path(&self, name: &str) -> PathBuf {
        self.dir.path().join(name)
    }

    fn p(&self, name: &str) -> &'static str {
        Box::leak(self.path(name).to_string_lossy().into_owned().into_boxed_str())
    }

    fn figure(&self, name: &str) -> Figure {
        let fig = Figure::load(self.path(name)).unwrap_or_else(|e| panic!("{name}: {e}"));
        let report = fig.validate();
        assert!(report.errors.is_empty(), "{name}: {:?}", report.errors);
        fig
    }

    fn polar(&self, name: &str, foil: &str, extra: &[&str]) {
        let mut args = vec![
            "polar",
            self.p(foil),
            "--alpha-min",
            "-2",
            "--alpha-max",
            "4",
            "--alpha-step",
            "2",
            "-r",
            "1e6",
            "-o",
            self.p(name),
        ];
        args.extend_from_slice(extra);
        ok(&args);
    }
}

/// The lines of axes `k`, in drawing order
fn lines(fig: &Figure, k: usize) -> Vec<&Line> {
    fig.ir().axes[k]
        .artists
        .iter()
        .filter_map(|a| match a {
            Artist::Line(l) => Some(l),
            _ => None,
        })
        .collect()
}

/// The key entries of axes `k`, in drawing order
fn names(fig: &Figure, k: usize) -> Vec<String> {
    lines(fig, k)
        .iter()
        .filter_map(|l| l.display_name.as_ref().map(|t| t.content.clone()))
        .collect()
}

/// A line's x and y values
fn data(fig: &Figure, line: &Line) -> (Vec<f64>, Vec<f64>) {
    let get = |id| fig.ir().data[&id].as_f64().unwrap().to_vec();
    (get(line.x), get(line.y))
}

fn param<'a>(fig: &'a Figure, name: &str) -> Option<&'a Parameter> {
    fig.parameters().get(name)
}

fn number(fig: &Figure, name: &str) -> f64 {
    match param(fig, name) {
        Some(Parameter::Number(v)) => *v,
        other => panic!("parameter {name}: {other:?}"),
    }
}

/// The axes indices of each link group of a dimension
fn links(fig: &Figure, dim: Dimension) -> Vec<Vec<usize>> {
    let ir = fig.ir();
    ir.links
        .iter()
        .filter(|l| l.dimension == dim)
        .map(|l| {
            let mut v: Vec<usize> = l
                .axes
                .iter()
                .map(|id| ir.axes.iter().position(|a| a.id == *id).unwrap())
                .collect();
            v.sort();
            v
        })
        .collect()
}

#[test]
fn geometry_inputs_overlay_panels_only() {
    let c = Case::new();
    // default output name: the input's stem plus _foil.fig, in the working directory
    ok_in(Some(c.dir.path()), &["plot", "foil", c.p("n0012.json")]);
    let fig = c.figure("n0012_foil.fig");
    assert_eq!(fig.ir().axes.len(), 1);
    assert!(fig.ir().panel_legends.is_empty(), "no key for a single geometry");
    // outline + one line of 60 notches (the default for geometry input), NaN between notches
    let ls = lines(&fig, 0);
    assert_eq!(ls.len(), 2);
    let (x, _) = data(&fig, ls[1]);
    assert_eq!(x.len(), 3 * 60);
    assert_eq!(x.iter().filter(|v| v.is_nan()).count(), 60);
    assert!(names(&fig, 0).is_empty());
    assert_eq!(param(&fig, "study"), Some(&Parameter::from("yfoil-plot")));
    assert_eq!(param(&fig, "figure"), Some(&Parameter::from("foil")));
    assert_eq!(param(&fig, "n_nodes"), Some(&Parameter::from(60_i64)));
    assert!(param(&fig, "alpha_deg").is_none(), "a geometry has no operating point");

    ok(&[
        "plot",
        "foil",
        c.p("n0012.json"),
        c.p("n0012_40.json"),
        "--panels",
        "dots",
        "-o",
        c.p("two.fig"),
    ]);
    let fig = c.figure("two.fig");
    // two outlines in their own colours, two node-dot lines with no stroke
    let ls = lines(&fig, 0);
    assert_eq!(ls.len(), 4);
    assert_ne!(ls[0].line.color, ls[1].line.color);
    let dots: Vec<_> = ls.iter().filter(|l| l.marker.shape == ironlab::Marker::Point).collect();
    assert_eq!(dots.len(), 2);
    assert!(dots.iter().all(|l| l.line.dash == ironlab::Dash::None));
    assert_eq!(names(&fig, 0), ["n0012", "n0012_40"], "the key names each geometry");
    assert_eq!(fig.ir().panel_legends.len(), 1);
    assert!(param(&fig, "n_nodes").is_none(), "the panel counts differ");
    assert_eq!(param(&fig, "points"), Some(&Parameter::from(2_i64)));

    fails(
        &["plot", "foil", c.p("n0012.json"), "--quantity", "dstar"],
        "geometry input has no boundary layer",
    );
    fails(
        &["plot", "foil", c.p("n0012.json"), "--wake"],
        "geometry input has no wake",
    );
    fails(&["plot", "foil", c.p("n0012.json"), "--alpha", "4"], "--alpha");
}

#[test]
fn analysis_inputs_draw_quantities_wake_and_markers() {
    let c = Case::new();
    ok(&[
        "plot",
        "foil",
        c.p("a4.json"),
        "--panels",
        "notches",
        "--wake",
        "--quantity",
        "dstar,theta",
        "-o",
        c.p("one.fig"),
    ]);
    let fig = c.figure("one.fig");
    assert_eq!(fig.ir().axes.len(), 1);
    assert_eq!(fig.ir().panel_legends.len(), 1, "one key, in a panel below the axes");
    let ls = lines(&fig, 0);
    // surface, wake line, aerofoil and wake notches, then per quantity: upper, lower, wake
    // upper, wake lower; then one line per marker
    let markers = ls.iter().filter(|l| l.line.dash == ironlab::Dash::None).count();
    assert_eq!(ls.len() - markers, 2 + 2 + 2 * 4);
    let (x, _) = data(&fig, ls[2]);
    assert_eq!(
        x.iter().filter(|v| v.is_nan()).count(),
        60,
        "one NaN after each node's notch"
    );
    let key = names(&fig, 0);
    assert!(key[0].starts_with("$\\delta^*$, scaled ×"), "{key:?}");
    assert!(key[1].starts_with("$\\theta$, scaled ×"), "{key:?}");
    // the stagnation circle, and a key entry per kind and side drawn (this case has a laminar
    // separation bubble)
    for name in ["stagnation", "transition (upper surface)"] {
        assert!(key.iter().any(|k| k == name), "{name} in {key:?}");
    }
    assert!(key.iter().any(|k| k.ends_with("transition (lower surface)")), "{key:?}");
    assert!(key.iter().any(|k| k.starts_with("separation (")), "{key:?}");
    assert!(key.iter().any(|k| k.starts_with("reattachment (")), "{key:?}");
    let circles = ls.iter().filter(|l| l.marker.shape == ironlab::Marker::Circle).count();
    assert_eq!(circles, 1);
    // one operating point: its inputs and outputs
    assert_eq!(number(&fig, "alpha_deg"), 4.0);
    assert_eq!(number(&fig, "re"), 1e6);
    assert_eq!(number(&fig, "mach"), 0.0);
    assert_eq!(param(&fig, "converged"), Some(&Parameter::Bool(true)));
    for name in [
        "cl",
        "cd",
        "cm",
        "x_transition_upper",
        "dstar_te_upper",
        "theta_te_lower",
    ] {
        assert!(number(&fig, name).is_finite(), "{name}");
    }
    assert!(
        fig.labels().is_empty(),
        "incompressible, free transition, Re 1e6: no regime tags"
    );

    // two design points × two quantities: four key entries, the second point dotted
    ok(&[
        "plot",
        "foil",
        c.p("a4.json"),
        c.p("a4m3.json"),
        "--quantity",
        "dstar,theta",
        "--label",
        "M=0",
        "--label",
        "M=0.3",
        "--no-markers",
        "-o",
        c.p("grid.fig.json"),
    ]);
    assert!(std::fs::read_to_string(c.path("grid.fig.json"))
        .unwrap()
        .starts_with('{'));
    let fig = c.figure("grid.fig.json");
    let key = names(&fig, 0);
    assert_eq!(key.len(), 4);
    assert!(key[0].starts_with("$\\delta^*$ at M=0, scaled ×"));
    assert!(key[3].starts_with("$\\theta$ at M=0.3, scaled ×"));
    let ls = lines(&fig, 0);
    assert_eq!(
        ls.iter().filter(|l| l.line.dash == ironlab::Dash::Dotted).count(),
        4,
        "second point dotted: upper and lower of each quantity"
    );
    assert!(ls.iter().all(|l| l.line.dash != ironlab::Dash::None), "no markers");
    // several points: only the conditions they share
    assert_eq!(number(&fig, "re"), 1e6);
    assert!(param(&fig, "mach").is_none());
    assert!(param(&fig, "cl").is_none() && param(&fig, "alpha_deg").is_none());

    // pictures are not written: the figure is the output
    fails(
        &["plot", "foil", c.p("a4.json"), "-o", c.p("one.png")],
        ".fig or .fig.json",
    );
    fails(&["plot", "foil", c.p("a4.json"), "--format", "png"], "--format");

    // mismatched panels cannot be overlaid with quantities
    ok(&[
        "analyse",
        c.p("n0012_40.json"),
        "--alpha",
        "4",
        "-r",
        "1e6",
        "-o",
        c.p("a4_40.json"),
    ]);
    fails(
        &["plot", "foil", c.p("a4.json"), c.p("a4_40.json"), "--quantity", "dstar"],
        "different panel geometry",
    );
    fails(&["plot", "foil", c.p("a4.json"), "--alpha", "4"], "needs a polar JSON");
    fails(&["plot", "foil", c.p("a4.json"), c.p("n0012.json")], "one kind");
    fails(
        &["plot", "foil", c.p("a4.json"), "--quantity", "nope"],
        "unknown BL quantity",
    );
}

#[test]
fn polar_distributions_select_design_points() {
    let c = Case::new();
    c.polar("polar.json", "n0012.json", &["--distributions"]);
    let text = std::fs::read_to_string(c.path("polar.json")).unwrap();
    assert!(text.contains("\"distributions\""));

    ok(&[
        "plot",
        "foil",
        c.p("polar.json"),
        "--alpha",
        "0,4",
        "--quantity",
        "dstar",
        "--wake",
        "-o",
        c.p("sweep.fig"),
    ]);
    let fig = c.figure("sweep.fig");
    let key = names(&fig, 0);
    let curves: Vec<&String> = key.iter().filter(|k| k.contains("scaled")).collect();
    assert_eq!(curves.len(), 2);
    assert!(curves[0].starts_with("$\\delta^*$ at α=0°, scaled ×"));
    assert!(curves[1].starts_with("$\\delta^*$ at α=4°, scaled ×"));
    assert!(!key.iter().any(|k| k.contains("α=2°")));
    assert_eq!(
        fig.ir().title.as_ref().map(|t| t.content.as_str()),
        Some("polar"),
        "the polar stem is the title"
    );
    // one scale factor for both points
    let ks: Vec<&str> = curves.iter().map(|k| k.split(", scaled ×").nth(1).unwrap()).collect();
    assert_eq!(ks[0], ks[1]);
    // two wake lines, one per point, the second dotted
    let wakes: Vec<_> = lines(&fig, 0)
        .into_iter()
        .filter(|l| {
            l.line.color
                == ironlab::ColorSpec::Rgba {
                    color: ironlab::Color::BLACK,
                }
                && l.marker.shape == ironlab::Marker::None
        })
        .collect();
    assert_eq!(wakes.len(), 2);
    assert_eq!(wakes[1].line.dash, ironlab::Dash::Dotted);

    // all embedded points by default (4 alphas: -2, 0, 2, 4)
    ok(&[
        "plot",
        "foil",
        c.p("polar.json"),
        "--quantity",
        "hk",
        "-o",
        c.p("all.fig"),
    ]);
    let fig = c.figure("all.fig");
    assert_eq!(
        names(&fig, 0).iter().filter(|k| k.starts_with("$H_k$ at α=")).count(),
        4
    );

    fails(
        &["plot", "foil", c.p("polar.json"), "--alpha", "3"],
        "no distribution at alpha = 3",
    );
    c.polar("plain.json", "n0012.json", &[]);
    fails(&["plot", "foil", c.p("plain.json")], "carries no distributions");
}

#[test]
fn analysis_figure_draws_minus_cp_and_ue_over_a_linked_x() {
    let c = Case::new();
    ok(&["plot", "analysis", c.p("a4.json")]);
    let fig = c.figure("a4.fig");
    let ir = fig.ir();
    assert_eq!(ir.axes.len(), 3, "−Cp, Ue/U∞ and the aerofoil strip");
    assert!(ir.panel_legends.is_empty(), "the key belongs to the Cp panel");
    assert_eq!(links(&fig, Dimension::X), vec![vec![0, 1, 2]]);
    assert!(links(&fig, Dimension::Y).is_empty());
    let label = |k: usize| ir.axes[k].y.label.as_ref().map(|t| t.content.clone());
    assert_eq!(label(0).as_deref(), Some("$-C_p$"));
    assert_eq!(label(1).as_deref(), Some("$U_e/U_\\infty$"));
    assert_eq!(names(&fig, 0), ["Upper surface", "Lower surface"]);
    assert!(names(&fig, 1).is_empty());
    assert_eq!(lines(&fig, 2).len(), 1);

    // the data are the record's, Cp negated
    let analysis: AnalysisOutput = serde_json::from_str(&std::fs::read_to_string(c.path("a4.json")).unwrap()).unwrap();
    let (xu, cpu, qu) = analysis.upper_surface().unwrap();
    let (x, y) = data(&fig, lines(&fig, 0)[0]);
    assert_eq!(x, xu);
    assert!(y.iter().zip(&cpu).all(|(a, b)| *a == -*b));
    assert_eq!(data(&fig, lines(&fig, 1)[0]).1, qu);

    assert_eq!(param(&fig, "figure"), Some(&Parameter::from("analysis")));
    assert_eq!(param(&fig, "foil"), Some(&Parameter::from("n0012")));
    assert_eq!(number(&fig, "alpha_deg"), 4.0);
    assert!(number(&fig, "cl").is_finite());

    // compressible: the regime tag and the Mach number
    ok(&["plot", "analysis", c.p("a4m3.json"), "-o", c.p("m3.fig")]);
    let fig = c.figure("m3.fig");
    assert_eq!(number(&fig, "mach"), 0.3);
    assert_eq!(fig.labels(), ["compressible"]);

    fails(
        &["plot", "analysis", c.p("a4.json"), "-o", c.p("a4.svg")],
        ".fig or .fig.json",
    );
    fails(&["plot", "analysis", c.p("n0012.json")], "analysis output");
}

#[test]
fn polar_figure_is_a_linked_sheet_with_one_key() {
    let c = Case::new();
    c.polar("p0012.json", "n0012.json", &["--label", "NACA 0012"]);
    c.polar("p0012_40.json", "n0012_40.json", &["--label", "N=40"]);

    ok_in(
        Some(c.dir.path()),
        &["plot", "polar", c.p("p0012.json"), c.p("p0012_40.json")],
    );
    let fig = c.figure("polar_comparison.fig");
    let ir = fig.ir();
    assert_eq!(ir.axes.len(), 4);
    assert_eq!(ir.panel_legends.len(), 1);
    // α across the CL–α, CM–α and CD–α panels; CL between CL–α and CL–CD
    assert_eq!(links(&fig, Dimension::X), vec![vec![0, 2, 3]]);
    assert_eq!(links(&fig, Dimension::Y), vec![vec![0, 1]]);
    let xlabel = |k: usize| ir.axes[k].x.label.as_ref().map(|t| t.content.clone()).unwrap();
    let ylabel = |k: usize| ir.axes[k].y.label.as_ref().map(|t| t.content.clone()).unwrap();
    assert_eq!(
        (0..4).map(|k| (xlabel(k), ylabel(k))).collect::<Vec<_>>(),
        [
            ("$\\alpha$ (deg)", "$C_L$"),
            ("$C_D$", "$C_L$"),
            ("$\\alpha$ (deg)", "$C_M$"),
            ("$\\alpha$ (deg)", "$C_D$"),
        ]
        .map(|(x, y)| (x.to_string(), y.to_string()))
    );
    for k in 0..4 {
        assert_eq!(names(&fig, k), ["NACA 0012", "N=40"], "panel {k}");
        assert!(matches!(ir.axes[k].legend, Some(ironlab::ir::Legend::Panel(_))));
        let ls = lines(&fig, k);
        assert_eq!(ls[0].marker.shape, ironlab::Marker::Cross);
        assert_eq!(ls[1].marker.shape, ironlab::Marker::Plus);
        assert_ne!(ls[0].line.color, ls[1].line.color);
        assert_eq!(data(&fig, ls[0]).0.len(), 4, "four valid points");
    }
    // the shared conditions, no per-polar summary
    assert_eq!(param(&fig, "figure"), Some(&Parameter::from("polar")));
    assert_eq!(number(&fig, "re"), 1e6);
    assert!(param(&fig, "foil").is_none(), "the two polars are of different files");
    assert!(param(&fig, "points").is_none());

    // one polar: its stem names the figure, and its summary is in the parameters
    ok(&["plot", "polar", c.p("p0012.json")]);
    let fig = c.figure("p0012.fig");
    assert_eq!(fig.ir().title.as_ref().unwrap().content, "NACA 0012");
    assert_eq!(param(&fig, "points"), Some(&Parameter::from(4_i64)));
    assert!(number(&fig, "cl_max").is_finite());
    assert_eq!(number(&fig, "alpha_cl_max_deg"), 4.0);

    fails(&["plot", "polar", c.p("a4.json")], "polar output");
}

#[test]
fn help_lists_plot_options() {
    let stdout = ok(&["plot", "foil", "--help"]);
    assert!(stdout.contains("--quantity"));
    assert!(stdout.contains("--max-offset"));
    assert!(stdout.contains("mass_defect"), "the quantity names BlQuantity accepts");
    assert!(!stdout.contains("--format") && !stdout.contains("--width"));
    assert!(stdout.contains(".fig.json"));
    let stdout = ok(&["polar", "--help"]);
    assert!(stdout.contains("--distributions"));
    assert!(Path::new(env!("CARGO_BIN_EXE_yfoil")).exists());
}
